import{z as i,x as l,o as e,c as d,q as t,j as A,D as a,d as r,s,S as B,b as o}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"影子银行的深化","description":"","frontmatter":{"title":"影子银行的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bm-shadow-deep.md","filePath":"econ/bm-shadow-deep.md","lastUpdated":1791413859000}'),h={name:"econ/bm-shadow-deep.md"};function p(c,E,m,D,C,u){const n=l("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="影子银行的深化" tabindex="-1">影子银行的深化 <a class="header-anchor" href="#影子银行的深化" aria-label="Permalink to &quot;影子银行的深化&quot;">​</a></h1><div class="epigraph"><p>影子银行不是没有银行的银行，而是把银行的资产负债表拆成一条流水线：每一环都在做期限转换，却没有一环叫银行。</p><footer>—— 据 Pozsar 等 2010、Gennaioli–Shleifer–Vishny 2013 整理</footer></div><p><a href="/econ/bm-regulatory-capital">上一课</a>把资本写成安全网的定价，也暴露出它的影子价格：分母上被做轻的资产、表外承接转换的管道。主干课的 <a href="/econ/shadow-run">影子挤兑</a>与 <a href="/econ/repo-mmf">回购与货基</a>钉过影子链怎么跑——haircut 跳升、停滚、破净；本课补「深化」：影子链的<strong>生产函数</strong>——「安全」债怎么被制造出来、信息不敏感为什么是设计目标而非运气、上一课的工具价格如何决定期限转换搬到哪里。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机构现金池每天滚动千亿量级的短期债，不可能逐笔尽调底层资产——若「安全」依赖尽职调查，这个市场根本转不起来。缺口是解释：影子债在好状态下为什么可以不动脑子地持有。Dang–Gorton–Holmström（与 Ordoñez）的回答是<strong>无知的均衡</strong>：债务被设计成信息不敏感——别人都不知道坏消息，你也没有激励去查；无人查账，债就像货币一样易手。这不是信息不对称的失灵，而是制造「类货币」的工艺；坏消息一旦到达，不敏感变敏感，集体尽调不可行，市场冻结——与第一课的协调阈值是同一机制换了记号。</p><p><span class="marginnote">术语翻译：「信息不敏感」指无论坏消息是否发生，持债人都不需要知道——设计目标就是让你「查了也不改变行动」，于是没人查；无知的均衡不是说大家被骗，而是查账对谁都不划算。</span></p><h3 id="流水线的解剖" tabindex="-1">流水线的解剖 <a class="header-anchor" href="#流水线的解剖" aria-label="Permalink to &quot;流水线的解剖&quot;">​</a></h3><p>影子链五道工序：<strong>发起</strong>（贷款，风险留在这里）、<strong>仓储</strong>（短债融资持有资产）、<strong>打包分层</strong>（拆成优先、夹层、劣后）、<strong>评级</strong>（给优先档开安全票）、<strong>持有</strong>（现金池用 ABCP 与回购接走优先档）。分层是关键：优先档在好状态几乎无风险。Gennaioli–Shleifer–Vishny 2013 补上需求侧：投资者忽略尾部时，创新者把新债造成「安全」并赚到溢价——安全是均衡的产物，不是谎言；忽略被打破，需求消失、价格跳变，杠杆只是放大器。抵押与保证金是影子的资本：回购的超额抵押在功能上等于资本金，只是不进 RWA、多数不在安全网内。上一课的接口在此闭合：分母价格与表外边界共同决定工序的选址——套利不是轶事，是选址变量。</p><p><span class="marginnote">Pozsar 等（纽约联储工作人员报告）估计危机前美国影子体系约 20 万亿美元，与表内体系同量级——「影子」不是边缘，是另一半。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读影子链先找三个量。一是<strong>哪一环做转换</strong>：错配不在贷款，在仓储与优先档的滚动之间。二是<strong>信息敏感性押在什么上</strong>：抵押品的价值与评级的假设各盖住多少坏状态。三是<strong>谁在末端持币</strong>：货基、司库、主权基金握着存款保险覆盖不了的量级，要大额、短期、可滚动且「不必想」的工具——影子债以更高收益供给同样的心理便利。三条读全，任何一环的抵押品被重估，上游仓储融资与下游评级假设同时断裂——Gorton–Metrick 2012 的 haircut 序列就是全链条的系统性保证金跳动。为什么要「神秘」：透明诱发个别审查，而个别审查在协调博弈里是传染的种子——影子债因此结构性模糊，监管者事前看不见：不是没人看，是被设计成不值得看。</p><p><span class="marginnote">直觉类比：回购的 haircut 就是影子的「资本金」——haircut 2% 相当于自带 50 倍杠杆时仅 2% 的自有资金；haircut 跳到 10%，等于监管一夜之间要求影子银行把本钱提高五倍，只是没人管它叫资本。</span></p>',12)),(e(),A(B,null,{default:a(()=>[s(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOAN%5B%22%E5%8F%91%E8%B5%B7%EF%BC%9A%E8%B4%B7%E6%AC%BE%22%5D%20--%3E%20WH%5B%22%E4%BB%93%E5%82%A8%EF%BC%9A%E7%9F%AD%E5%80%BA%E8%9E%8D%E8%B5%84%22%5D%20--%3E%20TR%5B%22%E6%89%93%E5%8C%85%E5%88%86%E5%B1%82%22%5D%0A%20%20TR%20--%3E%20RAT%5B%22%E8%AF%84%E7%BA%A7%E7%BB%99%E4%BC%98%E5%85%88%E6%A1%A3%E5%AE%89%E5%85%A8%E7%A5%A8%22%5D%20--%3E%20POOL%5B%22%E7%8E%B0%E9%87%91%E6%B1%A0%E6%8C%81%E6%9C%89%EF%BC%9AABCP%20%E4%B8%8E%E5%9B%9E%E8%B4%AD%22%5D%0A%20%20POOL%20--%3E%7C%22%E5%A5%BD%E7%8A%B6%E6%80%81%22%7C%20INSENS%5B%22%E4%BF%A1%E6%81%AF%E4%B8%8D%E6%95%8F%E6%84%9F%EF%BC%9A%E6%97%A0%E4%BA%BA%E6%9F%A5%E8%B4%A6%22%5D%0A%20%20POOL%20--%3E%7C%22%E5%9D%8F%E6%B6%88%E6%81%AF%22%7C%20SENS%5B%22%E4%BF%A1%E6%81%AF%E5%8F%98%E6%95%8F%E6%84%9F%EF%BC%9A%E9%9B%86%E4%BD%93%E5%B0%BD%E8%B0%83%E4%B8%8D%E5%8F%AF%E8%A1%8C%22%5D%20--%3E%20STOP%5B%22%E5%81%9C%E6%BB%9A%EF%BC%9Ahaircut%20%E8%B7%B3%E5%8D%87%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=o("p",null,"把本课与前两课焊在一起：第一课说可跑的债不限于存款，本课说转换工序也不限于表内——资本要求改变两者的相对价格，中介在合同与牌照的缝隙里重排工序：资产移出表、转换照做，资本与保险却不再覆盖。影子链的边界永远跟着资本要求走：要求收紧，工序再搬一格。所以治理从来不是「取缔」，而是把安全网的收费口径搬过去——哪一样接住，哪一环的无知均衡就失去燃料。",-1)),(e(),A(B,null,{default:a(()=>[s(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%A1%A8%E5%86%85%E8%B5%84%E6%9C%AC%E8%A6%81%E6%B1%82%E6%94%B6%E7%B4%A7%22%5D%20--%3E%20PRICE%5B%22%E8%A1%A8%E5%86%85%E5%81%9A%E6%9C%9F%E9%99%90%E8%BD%AC%E6%8D%A2%E5%8F%98%E8%B4%B5%22%5D%0A%20%20PRICE%20--%3E%20MOVE%5B%22%E5%B7%A5%E5%BA%8F%E6%90%AC%E5%87%BA%E8%A1%A8%E5%A4%96%E7%AE%A1%E9%81%93%22%5D%0A%20%20MOVE%20--%3E%20GAP%5B%22%E8%BD%AC%E6%8D%A2%E7%85%A7%E5%81%9A%EF%BC%9A%E8%B5%84%E6%9C%AC%E4%B8%8E%E4%BF%9D%E9%99%A9%E4%B8%8D%E5%86%8D%E8%A6%86%E7%9B%96%22%5D%0A%20%20REG%5B%22%E7%9B%91%E7%AE%A1%E6%8A%8A%E6%94%B6%E8%B4%B9%E5%8F%A3%E5%BE%84%E6%90%AC%E8%BF%87%E5%8E%BB%22%5D%20--%3E%20EVEN%5B%22%E6%97%A0%E7%9F%A5%E7%9A%84%E5%9D%87%E8%A1%A1%E6%96%AD%E7%B2%AE%EF%BC%9A%E5%BD%B1%E5%AD%90%E9%93%BE%E6%94%B6%E7%BC%A9%22%5D%0A%20%20EVEN%20--%3E%20RENET%5B%22%E5%B7%A5%E5%BA%8F%E5%86%8D%E5%AF%BB%E6%96%B0%E5%9D%80%E6%88%96%E5%9B%9E%E5%88%B0%E8%A1%A8%E5%86%85%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲挤兑机制与便利工具（<a href="/econ/shadow-run">影子挤兑</a>、<a href="/econ/repo-mmf">回购与货基</a> 已钉）；不写保证金螺旋——<a href="/econ/market-funding-liquidity">融资与市场流动性</a>的 Brunnermeier–Pedersen 是做市侧的另一条通道；评级激励的实证细节不展开。还有一条口径要划清：设计论不是共谋论——无知的均衡在好状态是帕累托改进，坏状态的脆弱性是它的价格；写成道德剧会错过结构（与 <a href="/econ/banking-crises-history">银行危机史</a> 一致）。救助怎么沿链开窗口，是下一课的事。</p><p><span class="marginnote">常见误区：把设计论读成共谋论。无知的均衡在好状态让所有人省下尽调成本，本身是帕累托改进；坏状态的冻结不是「有人撒谎被拆穿」，而是设计目标（不敏感）的代价到期——这是结构问题，不是道德剧。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>影子链是拆开的银行：发起、仓储、分层、评级、现金池，各环转换、无一叫银行。</li><li>安全债的设计目标是信息不敏感：无知的均衡；坏消息到达即集体尽调不可行。</li><li>haircut 是影子的资本；分母价格决定工序的表内外选址。</li><li>忽略尾部时创新能造「安全」，忽略被打破时需求消失、价格跳变。</li><li>治理是把安全网的收费口径搬过去，不是取缔。</li><li>出处：Pozsar 等 2010/2012；Dang–Gorton–Holmström–Ordoñez 2017；Gennaioli–Shleifer–Vishny 2013；Gorton–Metrick 2012。</li></ul>',5))])}const F=i(h,[["render",p]]);export{g as __pageData,F as default};
